import {
  Badge,
  Button,
  Card,
  CardContent,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@neshel-ui/components";
import { Grid } from "@neshel-ui/layout";
import { Paragraph } from "@neshel-ui/typography";

/**
 * Nested theme scopes: any element can set data-neshel-theme. "evergreen" and "aurora" are named
 * themes from this site's neshel.config.ts (generated by `neshel generate`).
 */
const themes = ["light", "dark", "evergreen", "aurora"] as const;

export default function ThemeScopes() {
  return (
    <Grid columns={{ base: 1, md: 2 }} space="4">
      {themes.map((theme) => (
        <div
          key={theme}
          data-neshel-theme={theme}
          className="rounded-xl bg-[var(--neshel-background)] p-4"
        >
          <Card>
            <CardHeader>
              <CardTitle>Theme “{theme}”</CardTitle>
            </CardHeader>
            <CardContent>
              <Paragraph size="sm" tone="muted">
                Same components, different tokens.
              </Paragraph>
            </CardContent>
            <CardFooter>
              <Button size="sm">Primary</Button>
              <Badge variant="accent">Accent</Badge>
            </CardFooter>
          </Card>
        </div>
      ))}
    </Grid>
  );
}
